const fs = require('fs');
const c = fs.readFileSync('D:/apps/FreelancerAdmin/src/components/layout/sidebar.tsx', 'utf8');
// Find navItems array - try different patterns
const lines = c.split('\n');
let inArray = false;
let count = 0;
let items = [];
for (const line of lines) {
  if (line.includes('const navItems')) inArray = true;
  if (inArray && line.includes('href:')) {
    count++;
    const labelMatch = line.match(/label:\s*"([^"]+)"/);
    if (labelMatch) items.push(labelMatch[1]);
  }
  if (inArray && line.trim() === '];') { inArray = false; break; }
}
console.log('navItems count:', count);
items.forEach(i => console.log(' -', i));
